steps.solutionCode:
const makeCounter = (start) => {
  let current = start;

  return () => {
    current = current + 1;
    return current;
  };
};

function getFirst() {
  const counter = makeCounter(10);

  return [counter(), counter()];
}

function alternate(startA, startB) {
  const makeCounter = (start) => {
    let current = start;

    return () => {
      current += 1;
      return current;
    };
  };

  const a = makeCounter(startA);
  const b = makeCounter(startB);

  return [a(), b(), a(), b(), a()];
}
